  function tr(text){return translations[text]||phraseTranslations[text]||text}
  function replacePhrases(v){let out=v;for(const [a,b] of Object.entries(phraseTranslations)){/* Evita corromper marcas como OPENCTI, OpenSearch etc. Palavras isoladas só são traduzidas por correspondência exata em tr(). */if(!/[\s/:+&.-]/.test(a))continue;if(out.includes(a))out=out.split(a).join(b);}return out}
  function localize(root){
    qsa(root,'.side-nav button').forEach(b=>{if(!b.dataset.sectionOriginal)b.dataset.sectionOriginal=b.textContent.trim();b.textContent=tr(b.dataset.sectionOriginal)});
    const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let n;const nodes=[];while(n=walker.nextNode())nodes.push(n);
    for(const node of nodes){const v=node.nodeValue;if(!v||!v.trim())continue;const trimmed=v.trim();if(translations[trimmed])node.nodeValue=v.replace(trimmed,translations[trimmed]);else node.nodeValue=replacePhrases(v);}
    qsa(root,'input[placeholder],textarea[placeholder]').forEach(el=>{const p=el.getAttribute('placeholder');if(translations[p])el.setAttribute('placeholder',translations[p])});
  }

  function statsRows(obj){return Object.entries(obj||{}).slice(0,14).map(([k,v])=>`<tr><td>${h(k)}</td><td>${h(Array.isArray(v)?v.join(', '):typeof v==='object'?JSON.stringify(v):v)}</td></tr>`).join('')}
  function sectionContent(app,sec){
    const s=BSC.state;
    if(app==='soc'){
      if(sec==='Discover')return `<div class="app-head"><div><h2>Descoberta de eventos</h2><p>Pesquisa livre sobre toda a telemetria do range, incluindo eventos que chegam em tempo real.</p></div><span class="tag pass">AUTO-REFRESH</span></div><div class="card"><div class="querybar"><input id="v7SiemQuery" value="${h(s.lastSiemQuery||'host:WS-FIN-021')}"/><button class="btn accent" data-v7-siem-run>Executar</button></div><div id="v7SiemResults" class="log-results"></div></div>`;
      if(sec==='Detections')return `<div class="app-head"><div><h2>Detecções</h2><p>Detecções correlacionadas por comportamento, identidade e rede.</p></div></div><div class="grid2"><div class="card"><h3>ATIVAS</h3>${[['Crítico','PowerShell + LSASS + C2','WS-FIN-021'],['Crítico','BLACK FROST - criptografia','FILE-HR-01'],['Alto','SMB fan-out lateral','JUMP-ADM-01'],['Alto','Credential stuffing','/api/login']].map(x=>`<article class="ticket-card"><header><strong>${x[0]}</strong><span class="tag critical">ATIVA</span></header><h4>${x[1]}</h4><p>${x[2]}</p></article>`).join('')}</div><div class="card"><h3>QUALIDADE</h3><table class="table"><tr><td>Precisão estimada</td><td>88%</td></tr><tr><td>Regras com tuning pendente</td><td>${s.detections?.filter(x=>x.falsePositives>10).length||0}</td></tr><tr><td>Fontes online</td><td>14/14</td></tr><tr><td>MITRE coberto no turno</td><td>T1059 · T1003 · T1021 · T1071</td></tr></table></div></div>`;
      if(sec==='Cases')return `<div class="app-head"><div><h2>Casos de segurança</h2><p>Casos abertos relacionados ao SOC.</p></div></div><div class="card"><table class="table"><tr><th>ID</th><th>Prioridade</th><th>Título</th><th>Status</th></tr>${s.tickets.filter(t=>/Security|SEC-|INC-|NDR|DFIR/.test(t.type+' '+t.id)).map(t=>`<tr><td>${h(t.id)}</td><td>${h(t.priority)}</td><td>${h(t.title)}</td><td>${h(tr(t.status))}</td></tr>`).join('')}</table></div>`;
      if(sec==='Rules')return `<div class="app-head"><div><h2>Regras de detecção</h2><p>Conteúdo Sigma-like e correlação local.</p></div></div><div class="card"><table class="table"><tr><th>ID</th><th>Regra</th><th>MITRE</th><th>FP</th></tr>${(s.detections||[]).map(d=>`<tr><td>${h(d.id)}</td><td>${h(d.title)}</td><td>${h(d.mitre)}</td><td>${d.falsePositives}</td></tr>`).join('')}</table><button class="btn" data-open="detections">Abrir Detection Engineering</button></div>`;
      if(sec==='MITRE ATT&CK')return `<div class="app-head"><div><h2>MITRE ATT&CK observado</h2><p>Técnicas presentes nos cenários ativos.</p></div></div><div class="mitre-grid">${['T1059 Command and Scripting','T1003 OS Credential Dumping','T1021 Remote Services','T1071 Application Layer Protocol','T1486 Data Encrypted for Impact','T1562 Impair Defenses','T1078 Valid Accounts','T1190 Exploit Public-Facing App'].map(x=>`<div class="mitre-card"><b>${x.split(' ')[0]}</b><span>${x.substring(x.indexOf(' ')+1)}</span></div>`).join('')}</div>`;
      if(sec==='Data sources')return `<div class="app-head"><div><h2>Fontes de dados</h2><p>Saúde de ingestão e última atividade.</p></div></div><div class="card"><table class="table"><tr><th>Fonte</th><th>Status</th><th>EPS</th><th>Último evento</th></tr>${[['Windows Security','Online',145,BSC.clock()],['Sysmon','Online',62,BSC.clock()],['XDR','Online',41,BSC.clock()],['EdgeGate NGFW','Online',88,BSC.clock()],['DNS','Online',54,BSC.clock()],['Proxy','Online',31,BSC.clock()],['NDR','Online',28,BSC.clock()],['Identity','Online',19,BSC.clock()],['WAF/API','Online',14,BSC.clock()]].map(x=>`<tr><td>${x[0]}</td><td><span class="tag pass">${x[1]}</span></td><td>${x[2]}</td><td>${x[3]}</td></tr>`).join('')}</table></div>`;
    }
    if(app==='firewall'){
      if(sec==='Interfaces')return `<div class="app-head"><div><h2>Interfaces</h2><p>Estado físico e lógico do cluster BSC-EDGE-HA.</p></div></div><div class="card"><table class="table"><tr><th>Porta</th><th>Alias</th><th>IP</th><th>Zona</th><th>Link</th></tr>${s.firewall.interfaces.map(i=>`<tr><td>${i.name}</td><td>${i.alias}</td><td>${i.ip}</td><td>${i.zone}</td><td><span class="tag ${i.link==='UP'?'pass':'critical'}">${i.link}</span></td></tr>`).join('')}</table></div>`;
      if(sec==='Routing')return `<div class="app-head"><div><h2>Roteamento</h2><p>Tabela ativa e preferências de saída.</p></div></div><div class="card"><table class="table"><tr><th>Destino</th><th>Gateway</th><th>Interface</th><th>Métrica</th></tr><tr><td>0.0.0.0/0</td><td>203.0.113.9</td><td>WAN1</td><td>10</td></tr><tr><td>0.0.0.0/0</td><td>198.51.100.9</td><td>WAN2</td><td>20</td></tr><tr><td>10.0.0.0/8</td><td>conectada</td><td>LACP1</td><td>0</td></tr></table></div>`;
      if(sec==='Firewall rules')return `<div class="app-head"><div><h2>Regras de firewall</h2><p>Políticas ativas, logging e hits.</p></div></div><div class="card"><table class="table"><tr><th>ID</th><th>Nome</th><th>Origem</th><th>Destino</th><th>Serviço</th><th>Ação</th><th>Log</th></tr>${s.firewall.rules.map(r=>`<tr><td>${r.id}</td><td>${h(r.name)}</td><td>${h(r.source)}</td><td>${h(r.destination)}</td><td>${h(r.service)}</td><td>${h(r.action)}</td><td>${r.logging?'SIM':'NÃO'}</td></tr>`).join('')}</table></div>`;
      if(sec==='HA')return `<div class="app-head"><div><h2>Alta disponibilidade</h2><p>Estado de heartbeat e sincronização de sessões.</p></div></div><div class="kpi-grid"><div class="kpi"><span>ATIVO</span><strong>${s.firewall.cluster.active}</strong></div><div class="kpi"><span>STANDBY</span><strong>${s.firewall.cluster.standby}</strong></div><div class="kpi"><span>HA2</span><strong class="${s.firewall.cluster.ha2==='UP'?'ok':'warning'}">${s.firewall.cluster.ha2}</strong></div><div class="kpi"><span>SYNC</span><strong>${s.firewall.cluster.sync}</strong></div></div><button class="btn" data-open="datacenter">Ver cabo HA2 no datacenter</button>`;
      if(sec==='Logs')return sectionContent('soc','Discover').replace('Descoberta de eventos','Logs do EdgeGate').replace('host:WS-FIN-021','source:firewall');
      if(sec==='Diagnostics')return `<div class="app-head"><div><h2>Diagnóstico</h2><p>Validação do cluster, links e alcance.</p></div></div><pre class="mini-console">Cluster: ${s.firewall.cluster.name}\nAtivo: ${s.firewall.cluster.active}\nStandby: ${s.firewall.cluster.standby}\nHA1: ${s.firewall.cluster.ha1}\nHA2: ${s.firewall.cluster.ha2}\nSession sync: ${s.firewall.cluster.sync}\nFailovers: ${s.firewall.cluster.failovers}</pre>`;
      if(['SD-WAN','NAT','VPN','IPS','Objects','Certificates'].includes(sec))return `<div class="app-head"><div><h2>${tr(sec)}</h2><p>Configuração operacional do EdgeGate.</p></div></div><div class="grid2"><div class="card"><h3>ESTADO ATUAL</h3><table class="table">${sec==='SD-WAN'?'<tr><td>WAN1</td><td>Primário · saudável</td></tr><tr><td>WAN2</td><td>Backup · saudável</td></tr>':sec==='NAT'?'<tr><td>ERP-PUBLISH</td><td>203.0.113.12 → APP-PROD-01:443</td></tr><tr><td>OUTBOUND-USERS</td><td>SNAT via WAN1</td></tr>':sec==='VPN'?'<tr><td>BSC-BSB</td><td>IPsec UP</td></tr><tr><td>BSC-RJ</td><td>IPsec UP</td></tr>':sec==='IPS'?'<tr><td>SERVER-PROTECT</td><td>Enforce · 14 signatures today</td></tr>':sec==='Objects'?'<tr><td>APP-PROD-01</td><td>10.40.10.21</td></tr><tr><td>DB-PROD-01</td><td>10.40.20.15</td></tr>':'<tr><td>portal.besafecorp.inc</td><td>Válido · 2027-05-18</td></tr>'}</table></div><div class="card"><h3>VALIDAÇÃO</h3><p class="muted">Este painel usa os mesmos objetos da CMDB e do simulador. Mudanças críticas continuam exigindo ticket/change e validação.</p></div></div>`;
    }
    if(app==='xdr'){
      if(sec==='Endpoints')return `<div class="app-head"><div><h2>Endpoints</h2><p>Inventário protegido pelo XDR.</p></div></div><div class="card"><table class="table"><tr><th>Endpoint</th><th>Risco</th><th>Isolamento</th><th>Evidência</th></tr>${Object.entries(s.xdr.endpoints).map(([id,e])=>`<tr><td>${id}</td><td>${e.risk}</td><td>${tr(e.isolation)}</td><td>${e.evidenceCollected?'Coletada':'Pendente'}</td></tr>`).join('')}</table></div>`;
      if(sec==='Detections')return `<div class="app-head"><div><h2>Detecções do endpoint</h2><p>Comportamentos de processo e rede correlacionados.</p></div></div><div class="card">${Object.entries(s.xdr.endpoints).map(([id,e])=>`<article class="ticket-card"><header><strong>${id}</strong><span class="tag ${e.risk==='Critical'?'critical':'pass'}">${e.risk}</span></header><p>${e.processes.filter(x=>x[3]!=='normal').map(x=>x[1]+' · '+x[3]).join(' | ')||'Sem detecções críticas'}</p></article>`).join('')}</div>`;
      if(sec==='Threat hunting')return `<div class="app-head"><div><h2>Threat hunting</h2><p>Hunt por IOC e comportamento em endpoints.</p></div></div><div class="card"><div class="querybar"><input id="v7Hunt" value="185.231.72.19"/><button class="btn accent" data-v7-hunt>Buscar</button></div><div id="v7HuntOut" class="timeline-note">Informe IP, processo, usuário ou domínio.</div></div>`;
      if(sec==='Live response')return `<div class="app-head"><div><h2>Resposta ao vivo</h2><p>Console seguro para coleta e diagnóstico dentro do simulador.</p></div></div><pre class="mini-console">live-response&gt; status\nSessão disponível para WS-FIN-021\nComandos simulados: ps | netstat | autoruns | collect triage</pre>`;
      if(sec==='Block list')return `<div class="app-head"><div><h2>Lista de bloqueio</h2><p>IOCs bloqueados pelo XDR.</p></div></div><div class="card">${s.xdr.blockedIOCs.length?s.xdr.blockedIOCs.map(x=>`<span class="evidence-chip">${h(x)}</span>`).join(' '):'<div class="empty">Nenhum IOC bloqueado ainda.</div>'}</div>`;
    }
    if(app==='itsm'){
      const typemap={'Incidents':'Incident','Security incidents':'Security','Changes':'Change','Requests':'Request','Problems':'Problem'};
      if(typemap[sec]){const f=s.tickets.filter(t=>(t.type+' '+t.id).toLowerCase().includes(typemap[sec].toLowerCase()));return `<div class="app-head"><div><h2>${tr(sec)}</h2><p>Fila operacional e SLAs.</p></div></div><div class="card"><table class="table"><tr><th>ID</th><th>Prioridade</th><th>Título</th><th>Status</th><th>SLA</th></tr>${f.map(t=>`<tr><td>${t.id}</td><td>${t.priority}</td><td>${h(t.title)}</td><td>${tr(t.status)}</td><td>${t.sla} min</td></tr>`).join('')}</table></div>`}
      if(sec==='CMDB')return sectionContent('cmdb','Assets');
    }
    if(app==='cmdb'&&sec!=='Assets')return `<div class="app-head"><div><h2>${tr(sec)}</h2><p>Visão canônica da CMDB da Be Safe Corp .Inc.</p></div></div><div class="card"><table class="table"><tr><th>Ativo</th><th>Tipo</th><th>Site</th><th>IP</th><th>Responsável</th></tr>${BSC_DATA.assets.map(a=>`<tr><td>${a.id}</td><td>${tr(a.type)}</td><td>${a.site}</td><td>${a.ip}</td><td>${a.owner}</td></tr>`).join('')}</table></div>`;
    if(app==='topology')return `<div class="app-head"><div><h2>${tr(sec)}</h2><p>Topologia oficial da empresa. A documentação completa está no Centro de Documentação.</p></div><button class="btn" data-open="docs">Abrir documentação</button></div><div class="topology-wrap"><img src="assets/topologia-be-safe-corp.svg" alt="Topologia Be Safe Corp"/></div>`;
    if(app==='report')return `<div class="app-head"><div><h2>${tr(sec)}</h2><p>Assessment individual por função e ações observadas.</p></div></div><div class="card"><p>Objetivos concluídos: <b>${Object.keys(s.completedObjectives).length}</b></p><p>Gaps registrados: <b>${s.gaps.length}</b></p><p>Ações auditadas: <b>${s.audit.length}</b></p><button class="btn accent" data-report-download>Baixar PDF com acentuação</button></div>`;
    // Fallback meaningful panel for every other menu item.
    const appName=(BSCApps.meta[app]||['',app])[1];
    return `<div class="app-head"><div><h2>${tr(sec)}</h2><p>${appName}: visão operacional integrada ao estado atual da Be Safe Corp .Inc.</p></div><span class="tag pass">ONLINE</span></div><div class="grid2"><div class="card"><h3>CONTEXTO DO TURNO</h3><p class="muted">Horário corporativo: ${BSC.clock()} · missão ativa: ${h(s.activeMission)} · eventos dinâmicos: ${(s.dynamicLogs||[]).length}</p><table class="table"><tr><td>Tickets abertos</td><td>${s.tickets.filter(t=>!['Resolved','Closed'].includes(t.status)).length}</td></tr><tr><td>Notificações não lidas</td><td>${s.notifications.filter(n=>!n.read).length}</td></tr><tr><td>Gaps observados</td><td>${s.gaps.length}</td></tr></table></div><div class="card"><h3>INTEGRAÇÃO</h3><p class="muted">Este menu está conectado ao mesmo estado de CMDB, incidentes e telemetria do range. Use a visão principal para executar ações e este painel para contexto do domínio.</p></div></div>`;
  }

  function bindSectionActions(root,app){
    qs(root,'[data-v7-siem-run]')?.addEventListener('click',()=>{const input=qs(root,'#v7SiemQuery');const q=input.value.trim();BSC.state.lastSiemQuery=q;BSC.audit('siem_query',{query:q,minutes:3});renderV7Logs(root,q)});
    qs(root,'#v7SiemQuery')?.addEventListener('keydown',e=>{if(e.key==='Enter')qs(root,'[data-v7-siem-run]')?.click()});
    qs(root,'[data-v7-hunt]')?.addEventListener('click',()=>{const q=qs(root,'#v7Hunt').value.toLowerCase();const hits=[];for(const [id,ep] of Object.entries(BSC.state.xdr.endpoints)){if(JSON.stringify(ep).toLowerCase().includes(q))hits.push(id)}qs(root,'#v7HuntOut').innerHTML=hits.length?`Encontrado em <b>${hits.join(', ')}</b>. Correlacione com SIEM e NDR.`:'Nenhum endpoint contém esse indicador na telemetria atual.';BSC.audit('xdr_hunt',{query:q,hits,minutes:4})});
    qsa(root,'[data-open]').forEach(b=>{if(!b.dataset.v7Bound){b.dataset.v7Bound='1';b.addEventListener('click',()=>window.BSCUI?.openApp(b.dataset.open,{ticket:b.dataset.ticket}))}});
    qs(root,'[data-report-download]')?.addEventListener('click',()=>window.BSCReport?.download());
    if(app==='soc'&&qs(root,'#v7SiemResults'))renderV7Logs(root,BSC.state.lastSiemQuery||'host:WS-FIN-021');
  }
  function renderV7Logs(root,q){
    const terms=(q||'').toLowerCase().replace(/\b(host|src|dst|user|source|event):/g,'').split(/\s+/).filter(Boolean);
    const logs=[...BSC_DATA.logs,...(BSC.state.dynamicLogs||[])].filter(l=>!terms.length||terms.every(t=>JSON.stringify(l).toLowerCase().includes(t))).slice(-250).reverse();
    const el=qs(root,'#v7SiemResults');if(!el)return;el.innerHTML=logs.length?logs.map(l=>`<div class="log-line"><span class="time">${h(l.ts)}</span><span class="source">${h(l.source)}</span><b>${h(l.host)}</b><span class="event">${h(l.event)}</span><span>${h(l.src||'-')}</span><span>${h(l.message)}</span></div>`).join(''):'<div class="empty">0 eventos. Amplie a consulta.</div>';
  }
  function enhanceNav(root,app){
    const content=qs(root,'.app-content'), buttons=qsa(root,'.side-nav button'); if(!content||!buttons.length)return;
    const originals=[...content.children].filter(x=>!x.classList.contains('v7-section-panel'));
    buttons.forEach((b,i)=>{const sec=b.dataset.sectionOriginal||b.textContent.trim();b.dataset.sectionOriginal=sec;b.onclick=()=>{buttons.forEach(x=>x.classList.remove('active'));b.classList.add('active');const old=qs(content,'.v7-section-panel');if(old)old.remove();if(i===0){originals.forEach(x=>x.classList.remove('v7-section-hidden'));return;} originals.forEach(x=>x.classList.add('v7-section-hidden'));const panel=document.createElement('div');panel.className='v7-section-panel';panel.innerHTML=sectionContent(app,sec);content.appendChild(panel);localize(panel);bindSectionActions(panel,app);BSC.audit('menu_navegacao',{app,sec,minutes:1});};});
  }

